<script setup>
import {computed,ref} from 'vue';
import {pilgrimagePoints,pilgrimageLicense} from '../../data/pilgrimage.js';
import {loadLocal,saveLocal,downloadJson} from '../../room/storage.js';
const selected=ref(pilgrimagePoints[0].id),unavailable=ref([]),message=ref('');
const bookmarks=ref(loadLocal('hitori-room:pilgrimage:v1',[],v=>{if(!Array.isArray(v))throw new Error();return v.filter(id=>pilgrimagePoints.some(p=>p.id===id));}));
const point=computed(()=>pilgrimagePoints.find(p=>p.id===selected.value));
const mapLink=p=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.title+' '+p.address);
function bookmark(p){bookmarks.value=bookmarks.value.includes(p.id)?bookmarks.value.filter(id=>id!==p.id):[...bookmarks.value,p.id];message.value=saveLocal('hitori-room:pilgrimage:v1',bookmarks.value)?'想去的地点已保存在本机。':'本机暂不能保存，可导出路线清单。';}
function exportRoute(){downloadJson({title:'一里小屋 · 下北泽巡礼清单',checked:'2026-11-13',places:pilgrimagePoints.filter(p=>!bookmarks.value.length||bookmarks.value.includes(p.id)).map(p=>({name:p.title,address:p.address,map:mapLink(p),source:p.source,comparison:p.mapUrl}))},'hitori-pilgrimage-route.json');message.value='已导出地点、地图与来源链接，方便出发前整理。';}
const time=s=>`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;
</script>
<template><section class="room-panel" aria-labelledby="pilgrimage-title"><p class="play-eyebrow">在现实里，遇见熟悉的街角</p><h2 id="pilgrimage-title">从车站走到舞台。</h2><p class="room-intro">三个真实地点，一条可以慢慢走的下北泽路线。地址依据运营方资料核对于2026-11-13；取景集数与画面来自Anitabi。下方是路线示意，实际步行导航请打开地图。</p><svg class="pilgrimage-map" viewBox="0 0 900 340" role="img" aria-label="下北泽车站、杂货店与SHELTER路线示意"><path d="M45 285Q165 250 170 120L440 125Q590 135 700 245L850 220" fill="none" stroke="#bd9caf" stroke-width="18"/><path d="M40 190H850M285 35V300M570 35V300" stroke="#d9c4c9" stroke-width="4"/><g v-for="(p,i) in pilgrimagePoints" :key="p.id" role="button" tabindex="0" :aria-label="'查看'+p.title" @click="selected=p.id" @keydown.enter="selected=p.id" @keydown.space.prevent="selected=p.id"><circle :cx="p.x" :cy="p.y" r="30" :fill="selected===p.id?'#8d5f7d':'#c291ac'" stroke="#fff5e7" stroke-width="3"/><text :x="p.x" :y="p.y+7" text-anchor="middle" fill="#fff6ef" font-size="20">{{i+1}}</text><text :x="p.x" :y="p.y+58" text-anchor="middle" fill="#715267" font-size="17">{{p.title}}</text></g><text x="28" y="40" font-family="monospace" font-size="15" fill="#ad7d97">A SMALL WALK / 路线示意</text></svg><div class="resource-actions"><button type="button" @click="exportRoute">导出{{bookmarks.length?'想去的地点':'路线清单'}} JSON ↓</button><a href="https://www.anitabi.cn/map?bangumiId=328609" target="_blank" rel="noopener noreferrer">打开完整巡礼地图 ↗</a></div><p class="room-status" role="status">{{message}}</p>
 <article v-if="point" class="resource-card"><small>正在查看 · {{point.name}}</small><h3>{{point.title}}</h3><p>{{point.address}}</p><p>{{point.note}}</p><img v-if="!unavailable.includes(point.id)" :src="point.image" :alt="point.title+'在动画中的取景截图'" width="320" height="180" loading="lazy" style="max-width:100%;height:auto" @error="unavailable.push(point.id)"><p v-else>取景截图暂不可用，可以打开原站查看对照。</p><p class="source-label">动画第{{point.ep}}集 · {{time(point.s)}}附近 · 取景资料署名：{{point.origin}}</p><div class="resource-actions"><button type="button" :aria-pressed="bookmarks.includes(point.id)" @click="bookmark(point)">{{bookmarks.includes(point.id)?'已记下，想去 ✓':'记下这个地点 ＋'}}</button><a :href="mapLink(point)" target="_blank" rel="noopener noreferrer">地图导航 ↗</a><a :href="point.mapUrl" target="_blank" rel="noopener noreferrer">动画 / 实景对照 ↗</a><a :href="point.source" target="_blank" rel="noopener noreferrer">运营方资料 ↗</a><a :href="point.originURL||point.originLink||point.mapUrl" target="_blank" rel="noopener noreferrer">取景原始来源 ↗</a></div></article>
 <div class="resource-grid" style="margin-top:20px"><article v-for="(p,i) in pilgrimagePoints" :key="p.id" class="resource-card"><small>路线第{{i+1}}站</small><h3>{{p.title}}</h3><p>{{p.address}}</p><button type="button" @click="selected=p.id">查看这一站 →</button></article></div><p class="room-hint">取景资料节选自 <a href="https://navi.anitabi.cn/docs/api/" target="_blank" rel="noopener noreferrer">Anitabi公开资料</a>，各贡献者署名见上方，按 <a :href="pilgrimageLicense" target="_blank" rel="noopener noreferrer">CC BY-NC-SA 4.0</a> 标注数据来源。地点说明与路线编排由本站整理。现场营业、通行与拍摄安排以运营方为准。</p></section></template>
